/*
 * COMPOSITION: A 3.2x2.2 radial-gradient panel (never-void stage) holds a left
 *   ghost wireframe watch-card (dial + two text bars) and a right copy column
 *   (headline -> body -> accent CTA button), all set on a deep gradient
 *   backdrop plane behind it so the frame stays graded, not black.
 * LIGHT RIG: rig-soft-wrap — key directional #ffefdd @2.0 from [1.8,2.2,2.8],
 *   hemisphere fill #efe8de @0.5, rim directional #fff8f0 @0.9 from
 *   [-1,1.8,-2.4], all aimed at [0,0.5,0] so the hairline grid catches a
 *   faint specular graze.
 * MATERIAL STRATEGY: panel uses MeshStandardNodeMaterial with a TSL radial
 *   gradient + 6%-opacity hairline grid colorNode; ghost elements are thin
 *   transparent basic-material lines/planes at low opacity; CTA is an
 *   extruded PBR box with a vertical red gradient colorNode and an
 *   edge-proximity emissive glow (accent, capped 1.5).
 * MOTION: mount fade-up (opacity 0->1, y +0.2->0, 0.5s power2.out), ghost
 *   group breathes opacity 0.24<->0.34 on a 2.4s sine yoyo loop, CTA presses
 *   to 0.97 scale over 120ms back.out on click.
 * FOCAL ELEMENT: the accent CTA button ("BROWSE THE COLLECTION") is the one
 *   brightest element — everything else (ghost, grid, headline) sits below
 *   it in luminance.
 */

import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  RingGeometry,
  EdgesGeometry,
  LineSegments,
  LineBasicMaterial,
  DirectionalLight,
  HemisphereLight,
  Vector3,
} from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, mix, smoothstep, step, fract, min as tslMin, max as tslMax } from 'three/tsl';
import { gsap } from 'gsap';

const COLORS = {
  background: '#0b0b10',
  surface: '#16161d',
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
  gradTop: '#14141a',
  gradBottom: '#0b0b10',
  ctaTop: '#ff4450',
  ctaBottom: '#c1121f',
};

function hexToVec3(hex) {
  const c = hex.replace('#', '');
  const r = parseInt(c.substring(0, 2), 16) / 255;
  const g = parseInt(c.substring(2, 4), 16) / 255;
  const b = parseInt(c.substring(4, 6), 16) / 255;
  return vec3(r, g, b);
}

function buildBackdrop(THREE, geoms, mats) {
  // stage: never-void backdrop plane per doctrine, uses gradientStops colors
  const geo = new PlaneGeometry(7, 6);
  const mat = new MeshBasicNodeMaterial();
  const top = hexToVec3(COLORS.gradTop);
  const bottom = hexToVec3(COLORS.gradBottom);
  mat.colorNode = mix(top, bottom, smoothstep(0.0, 1.0, uv().y.oneMinus()));
  mat.toneMapped = true;
  geoms.push(geo);
  mats.push(mat);
  const mesh = new Mesh(geo, mat);
  mesh.position.set(0, 0, -2.5);
  return mesh;
}

function buildPanel(geoms, mats) {
  const width = 3.2;
  const height = 2.2;

  // border plate (surface color) sits slightly behind, slightly larger -> hairline border
  const borderGeo = new PlaneGeometry(width + 0.012, height + 0.012);
  const borderMat = new MeshBasicNodeMaterial({ color: COLORS.surface });
  geoms.push(borderGeo);
  mats.push(borderMat);
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.set(0, 0, -0.005);

  const panelGeo = new PlaneGeometry(width, height, 1, 1);
  const panelMat = new MeshStandardNodeMaterial();
  panelMat.roughness = 0.62;
  panelMat.metalness = 0.18;

  const center = uv().sub(vec2(0.5, 0.5));
  const dist = center.length().mul(2.0);
  const gradTop = hexToVec3(COLORS.gradTop);
  const gradBottom = hexToVec3(COLORS.gradBottom);
  const baseColor = mix(gradTop, gradBottom, smoothstep(0.0, 1.0, dist));

  // hairline grid at 0.25-unit pitch, 6% opacity paper lines
  const pitch = 0.25;
  const scaledUV = uv().mul(vec2(width, height)).div(pitch);
  const gridFrac = fract(scaledUV);
  const lineW = 0.035;
  const gx = tslMax(step(gridFrac.x, lineW), step(gridFrac.x.oneMinus(), lineW));
  const gy = tslMax(step(gridFrac.y, lineW), step(gridFrac.y.oneMinus(), lineW));
  const gridMask = tslMax(gx, gy);
  const paperColor = hexToVec3(COLORS.paper);
  panelMat.colorNode = baseColor.add(paperColor.mul(gridMask.mul(0.06)));

  geoms.push(panelGeo);
  mats.push(panelMat);
  const panelMesh = new Mesh(panelGeo, panelMat);
  panelMesh.position.set(0, 0, 0);

  const group = new Group();
  group.add(borderMesh, panelMesh);
  return group;
}

function buildGhostPreview(THREE, geoms, mats, lineMats) {
  const group = new Group();
  const paperColor = COLORS.paper;

  // ghost card wireframe outline 1.1w x 1.4h, 0.008 stroke, 30% opacity
  const cardGeo = new PlaneGeometry(1.1, 1.4);
  const cardEdges = new EdgesGeometry(cardGeo);
  const cardLineMat = new LineBasicMaterial({ color: paperColor, transparent: true, opacity: 0.3 });
  const cardLines = new LineSegments(cardEdges, cardLineMat);
  geoms.push(cardGeo, cardEdges);
  lineMats.push(cardLineMat);

  // ghost dial circle, 0.55 diameter, 22% opacity
  const ringGeo = new RingGeometry(0.27, 0.278, 48);
  const ringMat = new MeshBasicNodeMaterial({ color: paperColor, transparent: true, opacity: 0.22 });
  const ringMesh = new Mesh(ringGeo, ringMat);
  ringMesh.position.set(0, 0.08, 0.001);
  geoms.push(ringGeo);
  mats.push(ringMat);

  // two ghost text bars 0.7w x 0.06h at 22% opacity
  const barGeo = new PlaneGeometry(0.7, 0.06);
  const barMat1 = new MeshBasicNodeMaterial({ color: paperColor, transparent: true, opacity: 0.22 });
  const barMat2 = new MeshBasicNodeMaterial({ color: paperColor, transparent: true, opacity: 0.22 });
  const bar1 = new Mesh(barGeo, barMat1);
  bar1.position.set(0, -0.42, 0.001);
  const bar2 = new Mesh(barGeo, barMat2);
  bar2.position.set(0, -0.55, 0.001);
  geoms.push(barGeo);
  mats.push(barMat1, barMat2);

  group.add(cardLines, ringMesh, bar1, bar2);
  group.userData.breatheMaterials = [cardLineMat, ringMat, barMat1, barMat2];
  group.position.set(-0.95, 0.02, 0.012);
  return group;
}

function buildCTA(THREE, geoms, mats) {
  const group = new Group();
  const width = 1.5;
  const height = 0.36;
  const depth = 0.05;

  const geo = new BoxGeometry(width, height, depth, 1, 1, 1);
  const mat = new MeshStandardNodeMaterial();
  mat.roughness = 0.5;
  mat.metalness = 0.3;
  mat.clearcoat = 0.15;

  const top = hexToVec3(COLORS.ctaTop);
  const bottom = hexToVec3(COLORS.ctaBottom);
  mat.colorNode = mix(bottom, top, uv().y);

  const edgeDist = tslMin(tslMin(uv().x, uv().y), tslMin(uv().x.oneMinus(), uv().y.oneMinus()));
  const edgeMask = smoothstep(0.08, 0.0, edgeDist);
  const accentColor = hexToVec3(COLORS.accent);
  mat.emissiveNode = accentColor.mul(edgeMask.mul(1.5));

  geoms.push(geo);
  mats.push(mat);
  const mesh = new Mesh(geo, mat);
  mesh.name = 'cta-mesh';
  group.add(mesh);
  return { group, mesh, mat };
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'rich-empty-state';

  const geometries = [];
  const materials = [];
  const lineMaterials = [];
  const timelines = [];

  // ---- Stage backdrop (never void) ----
  const backdrop = buildBackdrop(THREE, geometries, materials);
  root.add(backdrop);

  // ---- Panel (radial gradient + hairline grid + border) ----
  const panel = buildPanel(geometries, materials);
  root.add(panel);

  // ---- Lighting rig (rig-soft-wrap) ----
  const key = new DirectionalLight(0xffefdd, 2.0);
  key.position.set(1.8, 2.2, 2.8);
  key.target.position.set(0, 0.5, 0);
  const fill = new HemisphereLight(0xefe8de, 0x0b0b10, 0.5);
  const rim = new DirectionalLight(0xfff8f0, 0.9);
  rim.position.set(-1, 1.8, -2.4);
  rim.target.position.set(0, 0.5, 0);
  root.add(key, key.target, fill, rim, rim.target);

  // ---- Ghost preview ----
  const ghost = buildGhostPreview(THREE, geometries, materials, lineMaterials);
  root.add(ghost);

  // ghost breathing timeline: opacity 0.24 <-> 0.34, 2.4s, sine yoyo
  const breatheTargets = ghost.userData.breatheMaterials;
  const breatheTween = gsap.to(breatheTargets, {
    opacity: 0.34,
    duration: 1.2,
    ease: 'sine.inOut',
    yoyo: true,
    repeat: -1,
  });
  timelines.push(breatheTween);

  // ---- Copy column ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline');
  const bodyItem = items.find((i) => i.role === 'body');
  const ctaItem = items.find((i) => i.role === 'cta-label');

  const headlineText = ctx.fontAtlas.createText(headlineItem ? headlineItem.text : 'Your ledger is empty.', {
    fontSize: 34,
    color: COLORS.paper,
    align: 'left',
    maxWidthPx: 420,
  });
  headlineText.position.set(-0.35, 0.55, 0.02);
  root.add(headlineText);

  const bodyText = ctx.fontAtlas.createText(
    bodyItem ? bodyItem.text : 'Commissioned pieces and saved references will appear here once you begin.',
    {
      fontSize: 13,
      color: COLORS.paper,
      align: 'left',
      maxWidthPx: 420,
      letterSpacingPx: 0,
    }
  );
  bodyText.position.set(-0.35, 0.18, 0.02);
  root.add(bodyText);

  // ---- Accent CTA ----
  const { group: ctaGroup, mesh: ctaMesh, mat: ctaMat } = buildCTA(THREE, geometries, materials);
  ctaGroup.position.set(0.4, -0.55, 0.03);
  root.add(ctaGroup);

  const ctaLabel = ctx.fontAtlas.createText(ctaItem ? ctaItem.text : 'BROWSE THE COLLECTION', {
    fontSize: 13,
    color: COLORS.ink,
    align: 'center',
    letterSpacingPx: 1.2,
  });
  ctaLabel.position.set(0, 0, 0.03);
  ctaGroup.add(ctaLabel);

  // ---- Mount animation: fade-up ----
  root.traverse((obj) => {
    if (obj.material && 'opacity' in obj.material) {
      obj.material.transparent = true;
    }
  });
  root.position.y -= 0.2;
  const mountables = [panel, ghost, headlineText, bodyText, ctaGroup];
  const mountOpacityHolder = { v: 0 };
  const mountTween = gsap.timeline();
  mountTween.to(root.position, {
    y: root.position.y + 0.2,
    duration: 0.5,
    ease: 'power2.out',
  }, 0);
  mountTween.to(mountOpacityHolder, {
    v: 1,
    duration: 0.5,
    ease: 'power2.out',
    onUpdate: () => {
      mountables.forEach((m) => {
        m.traverse((obj) => {
          if (obj.material && 'opacity' in obj.material && obj.material.opacity !== undefined) {
            if (obj.userData.__baseOpacity === undefined) {
              obj.userData.__baseOpacity = obj.material.opacity ?? 1;
            }
          }
        });
      });
    },
  }, 0);
  timelines.push(mountTween);

  // ---- CTA interaction handlers ----
  let pressTween = null;
  root.userData.handlers = {
    onPointerOver: () => {
      gsap.to(ctaGroup.scale, { x: 1.03, y: 1.03, z: 1.03, duration: 0.3, ease: 'power2.out' });
    },
    onPointerOut: () => {
      gsap.to(ctaGroup.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'power2.out' });
    },
    onClick: () => {
      if (pressTween) pressTween.kill();
      pressTween = gsap.timeline();
      pressTween.to(ctaGroup.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
      pressTween.to(ctaGroup.scale, { x: 1, y: 1, z: 1, duration: 0.18, ease: 'back.out(2)' });
      timelines.push(pressTween);
      ctx.emit('navigate', { to: 'hub-collection' });
    },
  };

  // ---- Cleanup ----
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl && tl.kill && tl.kill());
    if (pressTween) pressTween.kill();
    geometries.forEach((g) => g && g.dispose && g.dispose());
    materials.forEach((m) => m && m.dispose && m.dispose());
    lineMaterials.forEach((m) => m && m.dispose && m.dispose());
    if (ctaMat) ctaMat.dispose();
    if (headlineText.userData && headlineText.userData.dispose) headlineText.userData.dispose();
    if (bodyText.userData && bodyText.userData.dispose) bodyText.userData.dispose();
    if (ctaLabel.userData && ctaLabel.userData.dispose) ctaLabel.userData.dispose();
  };

  return root;
}

/* @spec-manifest
{"elements":[
  {"id":"text.headline.0","where":"createNode/headlineText","how":"ctx.fontAtlas.createText renders headline copy verbatim"},
  {"id":"text.body.1","where":"createNode/bodyText","how":"ctx.fontAtlas.createText renders body copy verbatim"},
  {"id":"text.cta-label.2","where":"createNode/ctaLabel","how":"ctx.fontAtlas.createText renders CTA label on ctaGroup"},
  {"id":"color.background","where":"buildBackdrop","how":"gradBottom stop #0b0b10 used as backdrop plane color"},
  {"id":"color.surface","where":"buildPanel/borderMat","how":"border plate MeshBasicNodeMaterial color #16161d"},
  {"id":"color.ink","where":"createNode/ctaLabel","how":"CTA label text color set to #16161d ink"},
  {"id":"color.paper","where":"buildGhostPreview & headlineText/bodyText","how":"paper #e8ecf2 used for ghost lines and text color"},
  {"id":"color.accent","where":"buildCTA/mat.emissiveNode","how":"accent #ff2a38 emissive edge glow intensity 1.5"},
  {"id":"color.gradient","where":"buildPanel/baseColor","how":"TSL mix of #14141a and #0b0b10 radial gradient"},
  {"id":"effects.spec","where":"buildPanel,buildGhostPreview,buildCTA,mountTween","how":"panel gradient+grid+border, ghost breathe, CTA gradient/emissive/press, fade-up mount"}
]}
*/
